// The busy row's kaomoji thinking indicator (issue #1374): eight
// owner-approved two-tone faces replacing the braille spinner. Data +
// render helpers for the busy row; the model state (face index, picker
// seam, swap cadence) lives in FaTuiModel. Same library, so the private
// members stay private — mirrors the fa_tui_heartbeat.dart split.
part of 'fa_tui.dart';

/// One styled run of a kaomoji face: the text and whether it is a mouth
/// (blue #70a0e0) — everything else is an eye/face stroke (teal #60d0d0),
/// per the approved SVG sprite's `.t`/`.b` classes (issue #1374).
typedef KaomojiRun = (String text, bool mouth);

/// One kaomoji face: the primary runs and the ASCII-safe fallback runs
/// (narrow terminals, fonts without ◕‿¬). Faces whose primary text is
/// already ASCII carry the same runs twice.
final class KaomojiFace {
  const KaomojiFace(this.runs, this.fallbackRuns);

  final List<KaomojiRun> runs;
  final List<KaomojiRun> fallbackRuns;

  List<KaomojiRun> runsFor(bool ascii) => ascii ? fallbackRuns : runs;
}

/// The eight approved faces, in the issue's order. Segmentation mirrors
/// the SVG: `¬_¬`'s ASCII fallback `-_/` flattens both eyes to strokes
/// and the tilted stroke becomes the mouth; `o_o?`'s fallback drops the
/// curious `?`.
const List<KaomojiFace> kKaomojiFaces = [
  KaomojiFace(
    [('>', false), ('_', true), ('o', false)],
    [('>', false), ('_', true), ('o', false)],
  ),
  KaomojiFace(
    [('-', false), ('_', true), ('-', false)],
    [('-', false), ('_', true), ('-', false)],
  ),
  KaomojiFace(
    [('o', false), ('_', true), ('o', false)],
    [('o', false), ('_', true), ('o', false)],
  ),
  KaomojiFace(
    [('>', false), ('_', true), ('<', false)],
    [('>', false), ('_', true), ('<', false)],
  ),
  KaomojiFace(
    [('o', false), ('_', true), ('<', false)],
    [('o', false), ('_', true), ('<', false)],
  ),
  KaomojiFace(
    [('◕', false), ('‿', true), ('◕', false)],
    [('^', false), ('.', true), ('^', false)],
  ),
  KaomojiFace(
    [('¬', false), ('_', true), ('¬', false)],
    [('-', false), ('_', false), ('/', true)],
  ),
  KaomojiFace(
    [('o', false), ('_', true), ('o', false), ('?', true)],
    [('o', false), ('_', true), ('o', false)],
  ),
];

/// The face swaps every [kKaomojiSwapTicks] spinner ticks — 9 × 100 ms ≈
/// the issue's 0.9 s cadence — with a RANDOM pick, never a rotation.
const kKaomojiSwapTicks = 9;

/// Face-zone width: the widest face is `o_o?` (4 cells). Every face pads
/// into this fixed zone so a swap never moves a column right of it
/// (the #365 fixed-cell rule).
const kKaomojiFaceZoneCells = 4;

/// Below this width the fixed busy-row zones stop fitting, and cramped
/// terminals are also the likeliest to lack ◕‿¬ glyphs: render the
/// ASCII-safe fallback set (3 cells, 7-bit only).
const kKaomojiAsciiMinWidth = 36;

/// The process-wide random source of the default picker. Never read at a
/// call site — [FaTuiModel.kaomojiPick] is the seam; tests inject a
/// deterministic function instead.
final _kaomojiRandom = math.Random();

/// The default face picker: the `FA_KAOMOJI_FACE` pin when set (the
/// visual-fixture seam — every pick returns the pinned index), else a
/// uniform process-random pick.
int _defaultKaomojiPick(int max) {
  final pin = _kaomojiFacePin();
  return pin == null ? _kaomojiRandom.nextInt(max) : pin.clamp(0, max - 1);
}

/// The active `FA_KAOMOJI_FACE` pin: [FaTuiModel.kaomojiFacePinOverride]
/// wins (env is immutable in-process, so tests override statically), then
/// the env var, clamped into the face set; null = unpinned (the
/// production random cadence).
int? _kaomojiFacePin() {
  final override = FaTuiModel.kaomojiFacePinOverride;
  if (override != null) return override;
  final pin = int.tryParse(Platform.environment['FA_KAOMOJI_FACE'] ?? '');
  return pin?.clamp(0, kKaomojiFaces.length - 1);
}

/// Uniform over every face EXCEPT [current]: a swap that lands back on
/// the same face reads as a frozen row, so the raw pick in `0…len-2`
/// skips over [current]'s index.
int _nextKaomojiIndex(int Function(int max) pick, int current) {
  final raw = pick(kKaomojiFaces.length - 1);
  return raw >= current ? raw + 1 : raw;
}

/// The face's plain text (its exact cell count — every glyph is one
/// BMP code unit).
String _kaomojiPlainText(KaomojiFace face, bool ascii) {
  final b = StringBuffer();
  for (final (text, _) in face.runsFor(ascii)) {
    b.write(text);
  }
  return b.toString();
}

/// The face rendered two-tone: eye/face strokes in the brand teal, mouths
/// in the brand blue (issue #1374), through the theme controller's
/// profile-aware emitters.
String _kaomojiColored(KaomojiFace face, bool ascii) {
  final b = StringBuffer();
  for (final (text, mouth) in face.runsFor(ascii)) {
    b.write(mouth ? tuiKaomojiMouth(text) : tuiKaomojiEye(text));
  }
  return b.toString();
}

// The busy-row run machinery's message dispatch (the busy↔idle bracket,
// phase relabels, the wedge-watchdog tick and its kaomoji cadence), split
// out of fa_tui.dart (gh-1232 2800-line gate) as a library part — the
// same pattern as fa_tui_heartbeat.dart, so the members stay
// library-private and no public API moves.
part of 'fa_tui.dart';

extension FaTuiModelBusy on FaTuiModel {
  (Model, Cmd?) _handleBusyMsg(BusyMsg msg) {
    // An in-busy phase relabel (silent post-answer work like
    // auto-compaction or durable-memory extraction) takes priority.
    if (msg.busy && msg.phase != null) return _handlePhaseRelabel(msg);
    // A raw re-start while ALREADY busy (a trigger that bypassed the
    // controller's refcount): keep the elapsed window and the single tick
    // chain instead of stacking another one.
    if (msg.busy && busy) return _ignoreBusyRestart(msg);
    return _applyBusyTransition(msg);
  }

  /// The wedge watchdog's liveness push (issue #514): flips the busy row's
  /// label to `Stalled…` (and back) without touching the elapsed window —
  /// the stall is a STATE, not a phase relabel.
  (Model, Cmd?) _handleRunStalled(RunStalledMsg msg) =>
      (copyWith(runStalled: msg.stalled), null);

  /// A phase relabel on a BUSY model: swap the label over the SAME elapsed
  /// window and never schedule another tick here — extra chains would
  /// multiply repaint timers.
  (Model, Cmd?) _handlePhaseRelabel(BusyMsg msg) {
    final phase = msg.phase!;
    if (!busy) {
      // A relabel on an IDLE model is a post-run straggler (a compaction
      // finally-branch landing after the bracket released): dropping it is
      // the whole point — re-arming the spinner here wedged a session at
      // "Working… Ns" burning 100% CPU for hours (each chain re-renders
      // the full transcript every 100ms).
      faTuiBusyDiagnostics?.call('busy relabel dropped (idle) phase=$phase');
      return (this, null);
    }
    return (copyWith(busyPhase: phase), null);
  }

  (Model, Cmd?) _ignoreBusyRestart(BusyMsg msg) {
    faTuiBusyDiagnostics?.call(
      'busy re-start ignored (already busy) source=${msg.source}',
    );
    return (this, null);
  }

  /// The busy↔idle bracket itself. Kick the spinner loop when going busy;
  /// the loop stops itself on the first tick that finds the model idle
  /// again. Going idle also unpins the sticky user echo and clears any
  /// phase, so the next run starts as plain "Working…".
  (Model, Cmd?) _applyBusyTransition(BusyMsg msg) {
    faTuiBusyDiagnostics?.call(
      msg.busy
          ? 'busy on source=${msg.source ?? '?'}'
          : 'busy off source=${busySource.isEmpty ? '?' : busySource} '
                'elapsed=${busyStartedAtMs < 0 ? 0 : (DateTime.now().millisecondsSinceEpoch - busyStartedAtMs) ~/ 1000}s',
    );
    return (
      copyWith(
        busy: msg.busy,
        busyStartedAtMs: msg.busy ? DateTime.now().millisecondsSinceEpoch : -1,
        busyPhase: '',
        busySource: msg.busy ? (msg.source ?? '') : '',
        busyLastEventMs: msg.busy ? DateTime.now().millisecondsSinceEpoch : -1,
        // A new bracket always starts unstalled: the host pushes the
        // stall state per-episode, so a stale `Stalled…` must never
        // leak into the next run (issue #514).
        runStalled: msg.busy ? runStalled : false,
        spinnerFrame: 0,
        // A fresh run opens on a random face (issue #1374) — the same
        // seam the swap cadence uses, so tests stay deterministic.
        kaomojiFace: msg.busy ? kaomojiPick(kKaomojiFaces.length) : kaomojiFace,
        stickyLines: msg.busy ? null : const [],
        stickyIndex: msg.busy ? null : -1,
      ),
      msg.busy ? _scheduleSpinnerTick() : null,
    );
  }

  Cmd _scheduleSpinnerTick() {
    return () async {
      await Future<void>.delayed(const Duration(milliseconds: 100));
      return SpinnerTickMsg();
    };
  }

  (Model, Cmd?) _handleSpinnerTick() {
    if (!busy) return (this, null);
    final now = DateTime.now().millisecondsSinceEpoch;
    if (busyLastEventMs > 0 &&
        now - busyLastEventMs > FaTuiModel.busyWatchdogMs) {
      faTuiBusyDiagnostics?.call(
        'busy watchdog release source='
        '${busySource.isEmpty ? '?' : busySource} '
        'elapsed=${busyStartedAtMs < 0 ? 0 : (now - busyStartedAtMs) ~/ 1000}s '
        'quiet=${(now - busyLastEventMs) ~/ 1000}s',
      );
      return (
        copyWith(
          busy: false,
          busyStartedAtMs: -1,
          busyPhase: '',
          busySource: '',
          busyLastEventMs: -1,
          stickyLines: const [],
          stickyIndex: -1,
        ),
        null,
      );
    }
    // The tick counter drives the kaomoji cadence (issue #1374): every
    // kKaomojiSwapTicks ticks (~0.9 s at the 100 ms chain) the face is
    // re-picked — randomly, and never to the face already showing. The
    // chain itself dies with the busy bracket, so an idle row never
    // animates (AC4). A FA_KAOMOJI_FACE pin freezes the face entirely —
    // deterministic frames for the visual fixtures.
    final frame = spinnerFrame + 1;
    final face = frame % kKaomojiSwapTicks == 0 && _kaomojiFacePin() == null
        ? _nextKaomojiIndex(kaomojiPick, kaomojiFace)
        : kaomojiFace;
    return (
      copyWith(spinnerFrame: frame, kaomojiFace: face),
      _scheduleSpinnerTick(),
    );
  }
}

