+    for (var tick = 1; tick <= 2 * kKaomojiSwapTicks; tick++) {
+      m = m.update(SpinnerTickMsg()).$1 as FaTuiModel;
+      if (tick % kKaomojiSwapTicks != 0) {
+        expect(
+          m.kaomojiFace,
+          tick <= kKaomojiSwapTicks ? 3 : 6,
+          reason: 'tick $tick: no swap before the cadence boundary',
+        );
+      }
+    }
