+        contains('\x1b[38;2;112;160;224m_\x1b[0m'),
+        reason: 'mouth blue',
+      );
+      expect(
+        row,
+        contains('\x1b[38;2;96;208;208m<\x1b[0m'),
+        reason: 'eye teal',
