+      );
+      // Face 5 `◕‿◕` falls back to `^.^`.
+      expect(
+        busyRowOf(
+          faceModel(5, width: kKaomojiAsciiMinWidth - 1),
+          marker: 'Working…',
+        ),
+        contains('^.^'),
+      );
+    },
+  );
+
+  test(
