+    expect(
+      coloredBusyRowOf(m),
+      contains('\x1b[38;2;112;160;224m?'),
+      reason: 'face 7 = o_o? — the curious mouth stays blue',
+    );
+  });
+
+  test('herdr contract: every face matches the shipped busy_row regex', () {
