+
+  String busyRowOf(FaTuiModel m, {String marker = '· run'}) => m
+      .view()
+      .content
+      .split('\n')
+      .map((line) => line.replaceAll(ansi, ''))
+      .firstWhere((line) => line.contains(marker));
+
+  String coloredBusyRowOf(FaTuiModel m, {String marker = '· run'}) => m
