+    }
+    expect(
+      m.kaomojiFace,
+      3,
+      reason: 'the pin freezes the face across swap boundaries',
+    );
+    expect(busyRowOf(m), startsWith('>_< '), reason: 'face 3 renders >_<');
+  });
+
+  test('the pin clamps out-of-range values into the face set', () {
