+    onModelSelected: (_) async {},
+    buildSlashMenu: (_) => const [],
+    buildModelMenu: (_, _) => const [],
+    statusLine: () => '',
+    prompt: '',
+  );
+
+  FaTuiModel model({int width = 80, int Function(int max)? pick}) => FaTuiModel(
+    callbacks: callbacks(),
+    isExited: () => false,
+    termWidth: width,
+    kaomojiPick: pick,
+  );
+
+  /// A busy model pinned to face [face] (deterministic frames).
