+    var m = model(width: width, pick: (_) => face);
+    m = m.update(BusyMsg(true, source: 'run')).$1 as FaTuiModel;
+    return m.copyWith(kaomojiFace: face);
+  }
+
+  String busyRowOf(FaTuiModel m, {String marker = '· run'}) => m
+      .view()
+      .content
+      .split('\n')
