+    () {
+      var m = faceModel(2);
+      m = m.update(BusyMsg(false, source: 'run')).$1 as FaTuiModel;
+      final result = m.update(SpinnerTickMsg());
+      expect(result.$2, isNull, reason: 'no tick chain while idle');
