+      // At the boundary the unicode face renders again.
+      expect(
+        busyRowOf(
+          faceModel(6, width: kKaomojiAsciiMinWidth),
+          marker: 'Working…',
+        ),
+        contains('¬_¬'),
+      );
+      // Face 5 `◕‿◕` falls back to `^.^`.
+      expect(
+        busyRowOf(
+          faceModel(5, width: kKaomojiAsciiMinWidth - 1),
+          marker: 'Working…',
